draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);
  ctx.lineWidth = 4;
  ctx.strokeStyle = 'black';
  ctx.fillStyle = 'yellow';
  ctx.beginPath();
  ctx.rect(W/2-10, H/2-50, 20, 50 + 30 * (1 - Math.sin(t)));
  ctx.fill();
  ctx.stroke();
  ctx.fillStyle = 'orange';
  ctx.beginPath();
  ctx.rect(W/2-5, H/2-20, 10, 20 * (1 - Math.sin(t)));
  ctx.fill();
  ctx.stroke();
  ctx.fillStyle = 'black';
  ctx.beginPath();
  ctx.arc(W/2, H/2-70, 5, 0, 2 * Math.PI);
  ctx.fill();
  ctx.restore();
}
